                    return rule;
                }
                var patched = {};
                Object.keys(rule).forEach(function (k) { patched[k] = rule[k]; });
                patched.query = {};
                Object.keys(q).forEach(function (k) { patched.query[k] = q[k]; });
                patched.query.mutexMax = validationMutexMax;
                // Fill every free slot in ONE tick: with the limit-1 arm
