            if (c.indexOf('workflows/ci.yml/runs?head_sha=') !== -1) {
                return { workflow_runs: [GH857_GREEN_RUN] };
            }
            if (c.indexOf('runs?head_sha=') !== -1) {
                // Whole-head rollup: only the concluded green run —
                // NOTHING active behind the placeholder.
                return { workflow_runs: [GH857_GREEN_RUN] };
