function _githubGetRemoteRepoInfo() {
    try {
        var rawUrl = cli_execute_command({ command: 'git config --get remote.origin.url' }) || '';
        var remoteUrl = rawUrl.split('\n')
            .map(function(l) { return l.trim(); })
