            'after ' + validationLivenessModule.SILENT_UPDATE_MAX_FAILURES +
            ' consecutive push failures (gh-1070 AC3)');
    } catch (e1070) {
        console.warn('  ⚠️  ' + key + ' gh-1070 failure bookkeeping failed: ' +
                     (e1070.message || e1070));
    }
}

