    HOSTILE_TOKENS.forEach(function (tok) {
        assert.equal(commands[0].indexOf(tok), -1,
            'AC2: no untrusted byte in the shell string: ' + JSON.stringify(tok));
    });
});

suite('checkRunStamp: temp-file lifecycle (AC3 / UT-3)');

