    });
    var text = JSON.stringify(body);
    var back = JSON.parse(text);
    assert.equal(back.name, HOSTILE_NAME);
    assert.equal(back.output.summary, HOSTILE_SUMMARY);
    assert.equal(back.output.title, 'SM validation: success');
});

